import{_ as d,o as a,c as e,ag as r}from"./chunks/framework.D7Pdja0E.js";const u=JSON.parse('{"title":"시스템 설정","description":"","frontmatter":{},"headers":[],"relativePath":"04-org-admin-guide/settings.md","filePath":"04-org-admin-guide/settings.md","lastUpdated":1776160579000}'),o={name:"04-org-admin-guide/settings.md"};function i(h,t,l,n,s,b){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="시스템-설정" tabindex="-1">시스템 설정 <a class="header-anchor" href="#시스템-설정" aria-label="Permalink to &quot;시스템 설정&quot;">​</a></h1><p>기관 관리자는 조직의 시스템 연동 및 정책을 설정합니다.</p><h2 id="smtp-설정" tabindex="-1">SMTP 설정 <a class="header-anchor" href="#smtp-설정" aria-label="Permalink to &quot;SMTP 설정&quot;">​</a></h2><p>이메일 알림 발송을 위한 SMTP 서버를 설정합니다.</p><table tabindex="0"><thead><tr><th>설정</th><th>설명</th></tr></thead><tbody><tr><td>SMTP 서버</td><td>메일 서버 주소</td></tr><tr><td>포트</td><td>SMTP 포트 (587 권장)</td></tr><tr><td>암호화</td><td>TLS / STARTTLS</td></tr><tr><td>사용자</td><td>SMTP 인증 계정</td></tr><tr><td>비밀번호</td><td>SMTP 인증 비밀번호</td></tr><tr><td>발신자 이메일</td><td>알림 메일의 발신자 주소</td></tr></tbody></table><h3 id="테스트-발송" tabindex="-1">테스트 발송 <a class="header-anchor" href="#테스트-발송" aria-label="Permalink to &quot;테스트 발송&quot;">​</a></h3><p>설정 완료 후 <strong>&quot;테스트 메일 발송&quot;</strong> 버튼으로 정상 동작을 확인합니다.</p><h2 id="파일-저장소-설정" tabindex="-1">파일 저장소 설정 <a class="header-anchor" href="#파일-저장소-설정" aria-label="Permalink to &quot;파일 저장소 설정&quot;">​</a></h2><p>파일 업로드 저장소를 설정합니다.</p><table tabindex="0"><thead><tr><th>설정</th><th>설명</th></tr></thead><tbody><tr><td>저장소 유형</td><td>로컬 / S3 호환</td></tr><tr><td>최대 파일 크기</td><td>업로드 가능한 최대 파일 크기</td></tr><tr><td>허용 확장자</td><td>업로드 가능한 파일 확장자 목록</td></tr></tbody></table><h3 id="s3-호환-저장소" tabindex="-1">S3 호환 저장소 <a class="header-anchor" href="#s3-호환-저장소" aria-label="Permalink to &quot;S3 호환 저장소&quot;">​</a></h3><table tabindex="0"><thead><tr><th>설정</th><th>설명</th></tr></thead><tbody><tr><td>Endpoint</td><td>S3 엔드포인트 URL</td></tr><tr><td>Bucket</td><td>버킷 이름</td></tr><tr><td>Access Key</td><td>액세스 키</td></tr><tr><td>Secret Key</td><td>시크릿 키</td></tr><tr><td>Region</td><td>리전</td></tr></tbody></table><h2 id="dlp-데이터-유출-방지" tabindex="-1">DLP (데이터 유출 방지) <a class="header-anchor" href="#dlp-데이터-유출-방지" aria-label="Permalink to &quot;DLP (데이터 유출 방지)&quot;">​</a></h2><p>민감 정보의 유출을 방지하는 정책을 설정합니다.</p><h3 id="키워드-필터" tabindex="-1">키워드 필터 <a class="header-anchor" href="#키워드-필터" aria-label="Permalink to &quot;키워드 필터&quot;">​</a></h3><ol><li>관리 &gt; 시스템 설정 &gt; <strong>DLP</strong> 탭</li><li>차단할 키워드 패턴을 등록합니다.</li><li>메시지에 해당 패턴이 포함되면 전송이 차단됩니다.</li></ol><h3 id="파일-정책" tabindex="-1">파일 정책 <a class="header-anchor" href="#파일-정책" aria-label="Permalink to &quot;파일 정책&quot;">​</a></h3><ul><li>특정 확장자의 파일 업로드 차단</li><li>외부 공유 제한</li></ul><h2 id="조직-기본-설정" tabindex="-1">조직 기본 설정 <a class="header-anchor" href="#조직-기본-설정" aria-label="Permalink to &quot;조직 기본 설정&quot;">​</a></h2><table tabindex="0"><thead><tr><th>설정</th><th>설명</th></tr></thead><tbody><tr><td>조직 이름</td><td>화면에 표시되는 조직 이름</td></tr><tr><td>로고</td><td>사이드바 상단에 표시되는 로고 이미지</td></tr><tr><td>기본 언어</td><td>시스템 기본 언어 (한국어 / English)</td></tr><tr><td>타임존</td><td>시스템 기본 시간대</td></tr></tbody></table>',20)])])}const p=d(o,[["render",i]]);export{u as __pageData,p as default};
